class MultiDecorateTest(SimpleTestCase):
    def test_multi_decorate_single_decorator(self):
        """Test _multi_decorate with a single decorator."""
        def add_prefix(func):
            def wrapper(*args, **kwargs):
                return "prefix_" + func(*args, **kwargs)
            return wrapper

        def test_func():
            return "test"

        decorated = _multi_decorate(add_prefix, test_func)
        self.assertEqual(decorated(), "prefix_test")

    def test_multi_decorate_multiple_decorators(self):
        """Test _multi_decorate with multiple decorators."""
        def add_prefix(func):
            def wrapper(*args, **kwargs):
                return "prefix_" + func(*args, **kwargs)
            return wrapper

        def add_suffix(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_suffix"
            return wrapper

        def test_func():
            return "test"

        decorators = [add_prefix, add_suffix]
        decorated = _multi_decorate(decorators, test_func)
        self.assertEqual(decorated(), "prefix_test_suffix")

    def test_multi_decorate_empty_decorators(self):
        """Test _multi_decorate with empty decorators list."""
        def test_func():
            return "test"

        decorated = _multi_decorate([], test_func)
        self.assertEqual(decorated(), "test")

    def test_multi_decorate_with_non_iterable_decorator(self):
        """Test _multi_decorate with a non-iterable decorator."""
        def add_prefix(func):
            def wrapper(*args, **kwargs):
                return "prefix_" + func(*args, **kwargs)
            return wrapper

        def test_func():
            return "test"

        decorated = _multi_decorate(add_prefix, test_func)
        self.assertEqual(decorated(), "prefix_test")

    def test_multi_decorate_preserves_function_attributes(self):
        """Test that _multi_decorate preserves function attributes like __name__, __doc__, __dict__."""
        def test_func():
            """Test docstring."""
            return "test"

        test_func.anything = "test_dict"

        def add_prefix(func):
            def wrapper(*args, **kwargs):
                return "prefix_" + func(*args, **kwargs)
            return wrapper

        decorated = _multi_decorate(add_prefix, test_func)
        self.assertEqual(decorated.__name__, 'test_func')
        self.assertEqual(decorated.__doc__, 'Test docstring.')
        self.assertEqual(decorated.__dict__['anything'], 'test_dict')
