def test_pyobjmixin_getmodpath_with_nested_classes_and_functions(pytester: Pytester) -> None:
    """Test PyobjMixin.getmodpath with nested classes and functions to ensure correct module path construction."""
    pytester.makepyfile(
        test_module="""
        import pytest

        class OuterClass:
            def test_outer_method(self):
                pass

            class InnerClass:
                def test_inner_method(self):
                    pass

        def test_top_level_function():
            pass

        @pytest.mark.parametrize("value", [1, 2])
        def test_parametrized_function(value):
            pass
        """
    )

    # Collect all items
    items = pytester.getitems("test_module.py")

    # Test each item's getmodpath
    for item in items:
        modpath = item.getmodpath()

        # Verify the module path is correctly constructed
        if "OuterClass" in str(item):
            assert modpath == "test_module.OuterClass"
        elif "InnerClass" in str(item):
            assert modpath == "test_module.OuterClass.InnerClass"
        elif "test_top_level_function" in str(item):
            assert modpath == "test_module.test_top_level_function"
        elif "test_parametrized_function" in str(item):
            assert modpath == "test_module.test_parametrized_function"
