def test_hasinit(self, pytester: Pytester) -> None:
    """Test the hasinit function with various class definitions."""
    # Test case 1: Class with custom __init__
    item = pytester.getitem(
        """
        class TestClass:
            def __init__(self):
                pass
        """
    )
    assert hasinit(item.obj) is True

    # Test case 2: Class with default __init__ (inherited from object)
    item = pytester.getitem(
        """
        class TestClass:
            pass
        """
    )
    assert hasinit(item.obj) is False

    # Test case 3: Class with custom __init__ that is not the default
    item = pytester.getitem(
        """
        class TestClass:
            def __init__(self, arg):
                self.arg = arg
        """
    )
    assert hasinit(item.obj) is True

