@isolate_apps('check_framework', attr_name='apps')
@override_system_checks([checks.model_checks.check_all_models])
class ColumnNameClashTests(SimpleTestCase):
    def test_column_name_clash_in_same_model(self):
        class Model(models.Model):
            field1 = models.CharField(max_length=10)
            field2 = models.CharField(max_length=10)

            class Meta:
                db_table = 'test_table'
                # Force same db_column for both fields
                constraints = [
                    models.CheckConstraint(
                        check=models.Q(field1__isnull=False),
                        name='check_field1',
                        # This will cause a column name clash
                        # since both fields will have the same db_column
                        # if not explicitly set
                    )
                ]

        # Override the db_column to force a clash
        Model._meta.get_field('field1').db_column = 'clash_column'
        Model._meta.get_field('field2').db_column = 'clash_column'

        self.assertEqual(checks.run_checks(app_configs=self.apps.get_app_configs()), [
            Error(
                "Field 'field1' has column name 'clash_column' that is used by another field.",
                hint="Specify a 'db_column' for the field.",
                obj=Model,
                id='models.E007',
            ),
        ])

    def test_no_column_name_clash_with_different_column_names(self):
        class Model(models.Model):
            field1 = models.CharField(max_length=10, db_column='col1')
            field2 = models.CharField(max_length=10, db_column='col2')

        self.assertEqual(checks.run_checks(app_configs=self.apps.get_app_configs()), [])

    def test_column_name_clash_with_auto_generated_names(self):
        class Model(models.Model):
            field1 = models.CharField(max_length=10)
            field2 = models.CharField(max_length=10)

        # Both fields will have auto-generated column names
        # that might clash if they're too long or identical
        # after truncation
        self.assertEqual(checks.run_checks(app_configs=self.apps.get_app_configs()), [])

    def test_column_name_clash_with_m2m_field(self):
        class Model(models.Model):
            field1 = models.CharField(max_length=10)
            field2 = models.ManyToManyField('self')

        # The m2m field will have a column name that might clash
        # with field1's auto-generated column name
        self.assertEqual(checks.run_checks(app_configs=self.apps.get_app_configs()), [])

    def test_column_name_clash_with_custom_db_column(self):
        class Model(models.Model):
            field1 = models.CharField(max_length=10, db_column='custom_column')
            field2 = models.CharField(max_length=10, db_column='custom_column')

        self.assertEqual(checks.run_checks(app_configs=self.apps.get_app_configs()), [
            Error(
                "Field 'field2' has column name 'custom_column' that is used by another field.",
                hint="Specify a 'db_column' for the field.",
                obj=Model,
                id='models.E007',
            ),
        ])

    def test_column_name_clash_with_inherited_fields(self):
        class Parent(models.Model):
            field1 = models.CharField(max_length=10, db_column='inherited_column')

