class ModelFormMetaclassNewTestCase(TestCase):
    def test_model_form_metaclass_new_with_fields_and_exclude(self):
        """Test ModelFormMetaclass.__new__ with both fields and exclude parameters."""
        class TestModel:
            _meta = type('Meta', (), {'model': 'test_model', 'fields': ['field1', 'field2'], 'exclude': ['field3']})

        class TestForm:
            class Meta:
                model = TestModel
                fields = ['field1', 'field2']
                exclude = ['field3']

        # Create a new class using the metaclass
        new_class = ModelFormMetaclass.__new__(ModelFormMetaclass, 'TestForm', (BaseModelForm,), {})
        self.assertEqual(new_class._meta.model, 'test_model')
        self.assertEqual(new_class._meta.fields, ['field1', 'field2'])
        self.assertEqual(new_class._meta.exclude, ['field3'])

    def test_model_form_metaclass_new_with_string_fields(self):
        """Test ModelFormMetaclass.__new__ raises TypeError when fields is a string."""
        class TestForm:
            class Meta:
                model = 'test_model'
                fields = 'field1'  # This should raise TypeError

        with self.assertRaises(TypeError) as cm:
            ModelFormMetaclass.__new__(ModelFormMetaclass, 'TestForm', (BaseModelForm,), {})
        self.assertIn("fields cannot be a string", str(cm.exception))

    def test_model_form_metaclass_new_with_string_exclude(self):
        """Test ModelFormMetaclass.__new__ raises TypeError when exclude is a string."""
        class TestForm:
            class Meta:
                model = 'test_model'
                exclude = 'field1'  # This should raise TypeError

        with self.assertRaises(TypeError) as cm:
            ModelFormMetaclass.__new__(ModelFormMetaclass, 'TestForm', (BaseModelForm,), {})
        self.assertIn("exclude cannot be a string", str(cm.exception))

    def test_model_form_metaclass_new_with_all_fields(self):
        """Test ModelFormMetaclass.__new__ handles ALL_FIELDS correctly."""
        class TestModel:
            _meta = type('Meta', (), {'model': 'test_model'})

        class TestForm:
            class Meta:
                model = TestModel
                fields = ALL_FIELDS

        new_class = ModelFormMetaclass.__new__(ModelFormMetaclass, 'TestForm', (BaseModelForm,), {})
        self.assertIsNone(new_class._meta.fields)
        self.assertIsNone(new_class._meta.exclude)

    def test_model_form_metaclass_new_with_no_fields_or_exclude(self):
        """Test ModelFormMetaclass.__new__ raises ImproperlyConfigured when no fields or exclude."""
        class TestModel:
            _meta = type('Meta', (), {'model': 'test_model'})

        class TestForm:
            class Meta:
                model = TestModel

        with self.assertRaises(ImproperlyConfigured) as cm:
            ModelFormMetaclass.__new__(ModelFormMetaclass, 'TestForm', (BaseModelForm,), {})
        self.assertIn("Creating a ModelForm without either the 'fields' attribute or the 'exclude' attribute is prohibited", str(cm.exception))

    def test_model_form_metaclass_new_with_invalid_field_in_fields(self):
        """Test ModelFormMetaclass.__new__ raises FieldError when fields contains invalid field."""
        class TestModel:
            _meta = type('Meta', (), {'model': 'test_model'})

        class TestForm:
            class Meta:
                model = TestModel
                fields = ['nonexistent_field']

        with self.assertRaises(FieldError) as cm:
            ModelFormMetaclass.__new__(ModelFormMetaclass, 'TestForm', (BaseModelForm,), {})
        self.assertIn("Unknown field(s) (nonexistent_field) specified for test_model", str(cm.exception))
