def test_itermonomials_edge_cases():
    # Test with single variable and min_degree = max_degree
    assert set(itermonomials([x], 2, 2)) == {x**2}

    # Test with multiple variables and min_degrees = max_degrees
    assert set(itermonomials([x, y], [1, 1], [1, 1])) == {x*y}

    # Test with min_degrees equal to max_degrees and one variable having zero min/max
    assert set(itermonomials([x, y], [2, 0], [2, 0])) == {x**2}

    # Test with non-commutative variables and min_degrees = max_degrees
    i, j = symbols('i j', commutative=False)
    assert set(itermonomials([i, j], [1, 1], [1, 1])) == {i*j, j*i}

    # Test with empty variables list and min_degree = 0, max_degree = 0
    assert set(itermonomials([], 0, 0)) == {S.One}

    # Test with max_degrees = 0 and min_degrees = 0
    assert set(itermonomials([x, y], 0, 0)) == {S.One}

    # Test with max_degrees = 0 and min_degrees = 1 (should be empty)
    assert set(itermonomials([x, y], 0, 1)) == set()

    # Test with min_degrees = max_degrees = 0 for all variables
    assert set(itermonomials([x, y], [0, 0], [0, 0])) == {S.One}

    # Test with mixed commutative and non-commutative variables
    i, j = symbols('i j', commutative=False)
    assert set(itermonomials([x, i], [1, 1], [1, 1])) == {x*i, i*x}

    # Test with large max_degree but sparse result due to min_degree
    assert set(itermonomials([x, y], 5, 5)) == {x**5, x**4*y, x**3*y**2, x**2*y**3, x*y**4, y**5}

    # Test with min_degrees = max_degrees = 1 for non-commutative variables
    i, j = symbols('i j', commutative=False)
    assert set(itermonomials([i, j], [1, 1], [1, 1])) == {i*j, j*i}

    # Test with min_degrees = max_degrees = 2 for non-commutative variables
    i, j = symbols('i j', commutative=False)
    assert set(itermonomials([i, j], [2, 2], [2, 2])) == {i**2*j**2, i*j*i*j, i*j**2*i, i**2*j*i, j*i*j*i, j*i**2*j, j**2*i*j, j*i*j**2, i*j*j*i, j**2*i**2, i**2*j**2, j*i*i*j, i*j*i*j, j*i*j*i, i**2*j*i, j**2*i*j, i*j**2*i, j*i**2*j, i*j*j*i, j**2*i**2, i**2*j**2, j*i*i*j, i*j*i*j, j*i*j*i}
