def test_BlockMatrix_new_invalid_input():
    # Test that invalid input raises ValueError
    from sympy import MatrixSymbol, ZeroMatrix, symbols

    n, m = symbols('n m')
    X = MatrixSymbol('X', n, n)
    Y = MatrixSymbol('Y', m, m)

    # Test case 1: Empty list
    try:
        BlockMatrix([])
        assert False, "Expected ValueError for empty list"
    except ValueError:
        pass

    # Test case 2: Non-sequence input
    try:
        BlockMatrix(1)
        assert False, "Expected ValueError for non-sequence input"
    except ValueError:
        pass

    # Test case 3: Mixed matrix and non-matrix types
    try:
        BlockMatrix([[X, 1]])
        assert False, "Expected ValueError for mixed matrix and non-matrix types"
    except ValueError:
        pass

    # Test case 4: Inconsistent row lengths
