def test_get_col_items(self):
    # Test with regular variables
    var1 = xr.Variable("x", np.array([1, 2, 3]))
    var2 = xr.Variable("y", np.array([4, 5, 6]))
    mapping = {"var1": var1, "var2": var2}
    result = formatting._get_col_items(mapping)
    assert set(result) == {"var1", "var2"}

    # Test with IndexVariable that has level names
    index_var = xr.Variable(
        "time", np.array([1, 2, 3]), attrs={"units": "days"}
    ).to_index_variable()
    index_var = index_var.set_levels(
        {"level1": np.array([10, 20]), "level2": np.array([100, 200])}
    )
    mapping = {"time": index_var}
    result = formatting._get_col_items(mapping)
    assert set(result) == {"time", "level1", "level2"}

    # Test with nested MultiIndex
    multiindex_var = xr.Variable(
        "multi", np.array([1, 2, 3]), attrs={"units": "days"}
    ).to_index_variable()
    multiindex_var = multiindex_var.set_levels(
        {
            "level1": np.array([10, 20]),
            "level2": np.array([100, 200]),
            "level3": np.array([1000, 2000]),
        }
    )
    mapping = {"multi": multiindex_var}
    result = formatting._get_col_items(mapping)
    assert set(result) == {"multi", "level1", "level2", "level3"}

    # Test with empty mapping
    mapping = {}
    result = formatting._get_col_items(mapping)
    assert result == []

    # Test with no level names
    index_var = xr.Variable("x", np.array([1, 2, 3]))
    mapping = {"x": index_var}
    result = formatting._get_col_items(mapping)
    assert result == ["x"]
