def test_diff_mapping_repr(self):
    # Test basic functionality with simple mappings
    a = {"x": 1, "y": 2}
    b = {"x": 1, "y": 3}

    result = formatting._diff_mapping_repr(a, b, "equals", "Test", formatting.summarize_attr)
    expected = "Differing test:\nL   y: 2\nR   y: 3"
    assert result == expected

    # Test with different keys
    a = {"x": 1, "y": 2}
    b = {"x": 1, "z": 3}

    result = formatting._diff_mapping_repr(a, b, "equals", "Test", formatting.summarize_attr)
    expected = "Differing test:\nL   y: 2\nR   z: 3\nTest only on the right object:\n    z: 3"
    assert result == expected

    # Test with identical values
    a = {"x": 1, "y": 2}
    b = {"x": 1, "y": 2}

    result = formatting._diff_mapping_repr(a, b, "equals", "Test", formatting.summarize_attr)
    assert result == ""

    # Test with array-like values
    a = {"x": np.array([1, 2]), "y": np.array([3, 4])}
    b = {"x": np.array([1, 2]), "y": np.array([3, 5])}

    result = formatting._diff_mapping_repr(a, b, "equals", "Test", formatting.summarize_attr)
    expected = "Differing test:\nL   y: [3 4]\nR   y: [3 5]"
    assert result == expected

    # Test with callable compat
    def custom_compat(a, b):
        return a == b or (isinstance(a, np.ndarray) and isinstance(b, np.ndarray) and np.array_equal(a, b))

    a = {"x": np.array([1, 2]), "y": 3}
    b = {"x": np.array([1, 2]), "y": 4}

    result = formatting._diff_mapping_repr(a, b, custom_compat, "Test", formatting.summarize_attr)
    expected = "Differing test:\nL   y: 3\nR   y: 4"
    assert result == expected

    # Test with nested structure
    a = {"x": {"a": 1, "b": 2}, "y": 3}
    b = {"x": {"a": 1, "b": 3}, "y": 3}

    result = formatting._diff_mapping_repr(a, b, "equals", "Test", formatting.summarize_attr)
    expected = "Differing test:\nL   x: {'a': 1, 'b': 2}\nR   x: {'a': 1, 'b': 3}"
    assert result == expected
