        assert False, "Expected ValueError for non-sequence input"
    except ValueError:
        pass

    # Test case 2: Empty list
    try:
        BlockMatrix([])
        assert False, "Expected ValueError for empty list"
    except ValueError:
        pass

    # Test case 3: List with mixed types (not all matrices)
    try:
        BlockMatrix([[Matrix(2, 2, [1, 2, 3, 4]), 5]])
        assert False, "Expected ValueError for mixed types"
    except ValueError:
        pass

    # Test case 4: List with different number of matrices in each row
    try:
        BlockMatrix([[Matrix(2, 2, [1, 2, 3, 4]), Matrix(2, 2, [5, 6, 7, 8])],
                     [Matrix(2, 2, [9, 10, 11, 12])]])
        assert False, "Expected ValueError for inconsistent row lengths"
    except ValueError:
        pass

    # Test case 5: List with matrices of different row counts in a row
    try:
        BlockMatrix([[Matrix(2, 2, [1, 2, 3, 4]), Matrix(3, 2, [5, 6, 7, 8])]])
        assert False, "Expected ValueError for inconsistent row heights"
    except ValueError:
        pass

    # Test case 6: List with matrices of different column counts in a column
    try:
        BlockMatrix([[Matrix(2, 2, [1, 2, 3, 4]), Matrix(2, 3, [5, 6, 7, 8, 9, 10])]])
        assert False, "Expected ValueError for inconsistent column widths"
    except ValueError:
        pass

    # Test case 7: List with inconsistent total column counts
    try:
        BlockMatrix([[Matrix(2, 2, [1, 2, 3, 4]), Matrix(2, 2, [5, 6, 7, 8])],
